// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    // fuzz: caller key (so we can vm.addr and vm.prank) and deposit amount
    function testFuzz_property(uint256 pk, uint256 depositAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        pk = bound(pk, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep pk nonzero to get a valid EOA and keep depositAmount bounded reasonably
        vm.assume(pk != 0);
        depositAmount = bound(depositAmount, 0, 1 ether);

        address caller = vm.addr(pk);

        // Deploy a helper that ALWAYS reverts on receive to model a callee that makes zero-value calls revert
        Reverter rev = new Reverter();

        // Fund the caller so it can call deposit if needed
        vm.deal(caller, depositAmount + 1 ether);

        // If depositAmount > 0 deposit into c under the caller
        if (depositAmount > 0) {
            vm.prank(caller);
            // deposit payable
            c.deposit{value: depositAmount}();
        }

        // Now arrange for the caller to be the reverter contract when c attempts to send funds.
        // The contract C uses msg.sender when sending funds, so we must have c.call to rev by making the caller be rev.
        // We simulate the scenario: the external counterparty is rev (the mutant will call rev and may revert even on 0 value).

        // First test the behavior when caller has zero credit: according to the spec, reference should NOT revert
        // even if the callee would revert on receive of 0 value, because reference skips the call when credit==0.

        // Ensure rev has some ETH to accept/attempted send (not necessary but keep environment realistic)
        vm.deal(address(rev), 1 ether);

        bool ok;
        // make the call come from rev (so msg.sender inside C is rev)
        vm.prank(address(rev));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any inputs, when the caller (msg.sender) has zero credit, withdrawAll MUST NOT revert on the reference implementation.
        // The mutant which unconditionally calls msg.sender.call{value:0}("") can revert because some contracts (Reverter) revert even on zero-value calls.
        assertTrue(ok);

        // Additional step to ensure setup is admissible: if depositAmount > 0, withdrawing should succeed (smoke check) when invoked by that depositor.
        if (depositAmount > 0) {
            // Now have the depositor call withdrawAll; this should succeed on reference and for many mutants, but is not the distinguishing check.
            vm.prank(caller);
            // should not revert
            try c.withdrawAll() {
            } catch {
                // If this reverts, fail the test (reference should succeed)
                assertTrue(false);
            }
        }
    }
}

// Adversarial helper that ALWAYS reverts on receive/call so that even zero-value calls can revert
contract Reverter {
    fallback() external payable {
        revert("revert on any call");
    }
    receive() external payable {
        revert("revert on receive");
    }
}
